#[no_mangle]
pub unsafe extern "C" fn png_get_uint_31(mut png_ptr: png_const_structrp,
                                         mut buf: png_const_bytep)
 -> png_uint_32 {
    let mut uval: png_uint_32 =
        ((*buf as png_uint_32) <<
             24 as
                 std::os::raw::c_int).wrapping_add((*buf.offset(1 as std::os::raw::c_int as
                                                            isize) as
                                                png_uint_32) <<
                                               16 as
                                                   std::os::raw::c_int).wrapping_add((*buf.offset(2
                                                                                              as
                                                                                              std::os::raw::c_int
                                                                                              as
                                                                                              isize)
                                                                                  as
                                                                                  png_uint_32)
                                                                                 <<
                                                                                 8
                                                                                     as
                                                                                     std::os::raw::c_int).wrapping_add(*buf.offset(3
                                                                                                                               as
                                                                                                                               std::os::raw::c_int
                                                                                                                               as
                                                                                                                               isize)
                                                                                                                   as
                                                                                                                   png_uint_32);
    if uval > 0x7fffffff as std::os::raw::c_long as png_uint_32 {
        png_error(png_ptr,
                  b"PNG unsigned integer out of range\x00" as *const u8 as
                      *const std::os::raw::c_char);
    }
    return uval;
}
