        if length > 0 as std::os::raw::c_int as std::os::raw::c_uint {
            png_crc_read(png_ptr, (*png_ptr).unknown_chunk.data, length);
        }
        png_crc_finish(png_ptr, 0 as std::os::raw::c_int as png_uint_32);
        return 1 as std::os::raw::c_int
