                        let mut tmp_1: std::os::raw::c_uint =
                            (*dp_1 as std::os::raw::c_int &
                                 0xf0f as std::os::raw::c_int >>
                                     (4 as std::os::raw::c_int as
                                          std::os::raw::c_uint).wrapping_sub(dshift_1))
                                as std::os::raw::c_uint;
